impl<T: gx::Real> Rotor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[3];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t3);
        let t6 = t4 + t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (23 mul, 12 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Rotor<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t10 = t1 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t13);
        let t16 = t14 + t15;
        let t17 = t0.mul_add(t1, t6);
        let t18 = t0.mul_add(t3, t17);
        let t19 = t1.mul_add(t2, t10);
        let t20 = t2.mul_add(t3, t19);
        let t21 = t18 + t20;
        let t23 = t21.mul_add(T::from_i64(2), t16);
        let t24 = t23.recip();
        let t26 = t1 * t24;
        let t28 = t3 * t24;
        let t29 = t0.mul_add(t24, t26);
        let t30 = t2.mul_add(t24, t28);
        let t31 = t29 + t30;
        let t32 = x[0] * t31;
        let t33 = x[1] * t31;
        let t34 = x[2] * t31;
        let t35 = x[3] * t31;
        let t36 = -t33;
        let t37 = -t34;
        let t38 = -t35;
        Rotor::from_coeffs([t32, t36, t37, t38])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p3 = x[3] * x[3];
        let p4 = x[0].mul_add(x[0], p1);
        let p5 = x[2].mul_add(x[2], p3);
        let p6 = p4 + p5;
        let s0 = (p6).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Rotor::from_coeffs([t0, t1, t2, t3]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Rotor::from_coeffs(c).normalized()
    }

}

impl<T: gx::Coef> gx::NewtonStep for Rotor<(), T> {
    /// `x (3 â x ~x) / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[3];
        let t4 = x[0].mul_add(x[0], t1);
        let t5 = x[2].mul_add(x[2], t3);
        let t6 = t4 + t5;
        let t8 = (-t6).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t9 = x[0] * t8;
        let t10 = x[1] * t8;
        let t11 = x[2] * t8;
        let t12 = x[3] * t8;
        let t13 = t9 * T::from_ratio(3, 2);
        let t14 = t10 * T::from_ratio(3, 2);
        let t15 = t11 * T::from_ratio(3, 2);
        let t16 = t12 * T::from_ratio(3, 2);
        Rotor::from_coeffs([t13, t14, t15, t16])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

impl<T: gx::Real> gx::Log<Bivector<(), T>> for gx::Unit<Rotor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Bivector<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p1 = x[2] * x[2];
        let p3 = x[1].mul_add(x[1], p1);
        let p4 = x[3].mul_add(x[3], p3);
        let p5 = -p4;
        let [h0, h1] = gx::study::log_coeffs_rotation((x[0], T::from_i64(0)), (p5, T::from_i64(0)));
        let t0 = x[1] * h0;
        let t1 = x[2] * h0;
        let t2 = x[3] * h0;
        Bivector::from_coeffs([t0, t1, t2])
        })
    }
}

