    pub const fn new(e1: T, e2: T, e3: T, e123: T) -> Self {
        Odd { c: [e1, e2, e3, e123] }
    }

    /// gx::Prepare this versor's action on kind `X` for applying it to many objects (see
    /// [`gx::Prepared`]).
