impl<S: gx::Slots, T: gx::Coef> gx::Transform<Vector<S, T>> for Vector<(), T> {
    type Output = Vector<S, T>;
    #[inline(always)]
    fn transform(self, x: Vector<S, T>) -> Vector<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t2 = v[2] * v[2];
        let t3 = v[0] * v[1];
        let t4 = v[0] * v[2];
        let t5 = v[1] * v[2];
        let t6 = t0 - t1;
        let t7 = t6 - t2;
        let t8 = t2 + t6;
        let t9 = t0 + t1;
        let t10 = t9 - t2;
        let t13 = xv[2] * t4;
        let t16 = xv[2] * t5;
        let t18 = xv[1] * t5;
        let t20 = xv[1].mul_add(t3, t13);
        let t21 = t20 * T::from_i64(2);
        let t22 = xv[0].mul_add(t7, t21);
        let t23 = xv[0].mul_add(t3, t16);
        let t24 = t23 * T::from_i64(2);
        let t25 = (-xv[1]).mul_add(t8, t24);
        let t26 = xv[0].mul_add(t4, t18);
        let t27 = t26 * T::from_i64(2);
        let t28 = (-xv[2]).mul_add(t10, t27);
            return Vector { c: gx::slots::from_values::<S, T, 3>([t22, t25, t28]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[2] * v[2];
        let m3 = v[0] * v[1];
        let m4 = v[0] * v[2];
        let m5 = v[1] * v[2];
        let m6 = m0 - m1;
        let m7 = m6 - m2;
        let m8 = m3 * T::from_i64(2);
        let m9 = m4 * T::from_i64(2);
        let m10 = m2 + m6;
        let m11 = -m10;
        let m12 = m5 * T::from_i64(2);
        let m13 = m2 - m0;
        let m14 = m13 - m1;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Vector { c: [(x[0].scale(m7) + x[1].scale(m8) + x[2].scale(m9)).0, (x[0].scale(m8) + x[1].scale(m11) + x[2].scale(m12)).0, (x[0].scale(m9) + x[1].scale(m12) + x[2].scale(m14)).0] }
    }
}

