impl<S: gx::Slots, T: gx::Coef> gx::Transform<Rotor<S, T>> for gx::Unit<Rotor<(), T>> {
    type Output = Rotor<S, T>;
    #[inline(always)]
    fn transform(self, x: Rotor<S, T>) -> Rotor<S, T> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[1] * v[1];
        let u4 = v[0].mul_add(v[0], u1);
        let u5 = v[2].mul_add(v[2], u4);
        let u6 = v[3].mul_add(v[3], -T::from_i64(1));
        let u7 = u5 + u6;
            T::check_unit(&[u7]);
        }
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t2 = v[3] * xv[2];
        let t3 = v[0].mul_add(xv[1], t2);
        let t4 = (-v[2]).mul_add(xv[3], t3);
        let t6 = v[1] * xv[3];
        let t8 = v[0].mul_add(xv[2], t6);
        let t9 = (-v[3]).mul_add(xv[1], t8);
        let t12 = v[2] * xv[1];
        let t13 = v[0].mul_add(xv[3], t12);
        let t14 = (-v[1]).mul_add(xv[2], t13);
        let t16 = v[3] * t9;
        let t17 = v[1] * t14;
        let t20 = v[2] * t4;
        let t21 = (-v[2]).mul_add(t14, t16);
        let t24 = v[1] * v[1];
        let t26 = v[3] * v[3];
        let t27 = v[0].mul_add(v[0], t24);
        let t28 = v[2].mul_add(v[2], t26);
        let t29 = t27 + t28;
        let t30 = xv[1] * t29;
        let t31 = t21.mul_add(T::from_i64(2), t30);
        let t32 = (-v[3]).mul_add(t4, t17);
        let t34 = xv[2] * t29;
        let t35 = t32.mul_add(T::from_i64(2), t34);
        let t36 = (-v[1]).mul_add(t9, t20);
        let t38 = xv[3] * t29;
        let t39 = t36.mul_add(T::from_i64(2), t38);
        let t40 = xv[0] * t29;
            return Rotor { c: gx::slots::from_values::<S, T, 4>([t40, t31, t35, t39]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[2] * v[2];
        let m3 = v[3] * v[3];
        let m4 = v[0] * v[1];
        let m5 = v[0] * v[2];
        let m6 = v[0] * v[3];
        let m7 = v[1] * v[2];
        let m8 = v[1] * v[3];
        let m9 = v[2] * v[3];
        let m10 = m0 - m1;
        let m11 = m2 - m3;
        let m12 = m0 + m1;
        let m13 = m2 + m3;
        let m14 = m12 - m13;
        let m15 = m6 + m7;
        let m16 = m15 * T::from_i64(2);
        let m17 = m8 - m5;
        let m18 = m17 * T::from_i64(2);
        let m19 = m7 - m6;
        let m20 = m19 * T::from_i64(2);
        let m21 = m10 + m11;
        let m22 = m4 + m9;
        let m23 = m22 * T::from_i64(2);
        let m24 = m5 + m8;
        let m25 = m24 * T::from_i64(2);
        let m26 = m9 - m4;
        let m27 = m26 * T::from_i64(2);
        let m28 = m10 - m11;
        let m29 = m12 + m13;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Rotor { c: [(x[0].scale(m29)).0, (x[1].scale(m14) + x[2].scale(m16) + x[3].scale(m18)).0, (x[1].scale(m20) + x[2].scale(m21) + x[3].scale(m23)).0, (x[1].scale(m25) + x[2].scale(m27) + x[3].scale(m28)).0] }
    }
}

