        let m7 = v[1] * v[2];
        let m8 = v[1] * v[3];
        let m9 = v[2] * v[3];
        let m10 = m0 - m1;
        let m11 = m2 - m3;
        let m12 = m10 - m11;
        let m13 = m4 - m9;
        let m14 = m13 * T::from_i64(2);
