        let m16 = m15 * T::from_i64(2);
        let m17 = m4 + m9;
        let m18 = m17 * T::from_i64(2);
        let m19 = m10 + m11;
        let m20 = -m19;
        let m21 = m7 - m6;
        let m22 = m21 * T::from_i64(2);
        let m23 = m5 - m8;
        let m24 = m23 * T::from_i64(2);
        let m25 = m6 + m7;
        let m26 = m25 * T::from_i64(2);
        let m27 = m2 + m3;
        let m28 = m0 + m1;
        let m29 = m27 - m28;
