        let t47 = (-xv[3]).mul_add(t20, t28);
        let t48 = t47 * T::from_i64(2);
        let t49 = (-xv[2]).mul_add(t19, t48);
        let t50 = xv[1].mul_add(t21, t32);
        let t51 = t50 * T::from_i64(2);
