impl<S: gx::Slots, T: gx::Coef> gx::TransformInv<Multivector<S, T>> for gx::Unit<Odd<(), T>> {
    type Output = Multivector<S, T>;
    #[inline(always)]
    fn transform_inv(self, x: Multivector<S, T>) -> Multivector<S, T> {
        gx::Transform::transform(gx::Unit::new_unchecked(self.into_inner().reverse()), x)
    }
}

impl<T: gx::Coef> gx::Prepare<Multivector> for gx::Unit<Odd<(), T>> {
    type Output = gx::Prepared<gx::Unit<Odd>, Multivector, T, 10>;
    #[inline]
    fn prepare(self) -> gx::Prepared<gx::Unit<Odd>, Multivector, T, 10> {
        let v = self.into_inner().c;
        #[cfg(feature = "check-units")]
        {
        let u1 = v[1] * v[1];
        let u4 = v[0].mul_add(v[0], u1);
        let u5 = v[2].mul_add(v[2], u4);
        let u6 = v[3].mul_add(v[3], -T::from_i64(1));
        let u7 = u5 + u6;
            T::check_unit(&[u7]);
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[2] * v[2];
        let m3 = v[3] * v[3];
        let m4 = v[0] * v[1];
        let m5 = v[0] * v[2];
        let m6 = v[0] * v[3];
        let m7 = v[1] * v[2];
        let m8 = v[1] * v[3];
        let m9 = v[2] * v[3];
        let m10 = m0 - m1;
        let m11 = m2 - m3;
        let m12 = m0 + m1;
        let m13 = m2 + m3;
        let m14 = m4 - m9;
        let m15 = m4 + m9;
        let m16 = m5 - m8;
        let m17 = m5 + m8;
        let m18 = m6 - m7;
        let m19 = m6 + m7;
        let m20 = m10 - m11;
        let m21 = m10 + m11;
        let m22 = m12 - m13;
        let m23 = m14 * T::from_i64(2);
        let m24 = m17 * T::from_i64(2);
        let m25 = m15 * T::from_i64(2);
        let m26 = -m21;
        let m27 = m18 * T::from_i64(2);
        let m28 = -m27;
        let m29 = m16 * T::from_i64(2);
        let m30 = m19 * T::from_i64(2);
        let m31 = -m22;
        let m32 = m12 + m13;
        gx::Prepared::from_entries([m32, m20, m23, m24, m25, m26, m28, m29, m30, m31])
    }
}

impl<S: gx::Slots, T: gx::Coef> gx::Transform<Multivector<S, T>> for gx::Prepared<gx::Unit<Odd>, Multivector, T, 10> {
    type Output = Multivector<S, T>;
    #[inline(always)]
    fn transform(self, x: Multivector<S, T>) -> Multivector<S, T> {
        let m = self.m;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Multivector { c: [(x[0].scale(m[0])).0, (x[1].scale(m[1]) + x[2].scale(m[2]) + x[3].scale(m[3])).0, (x[1].scale(m[4]) + x[2].scale(m[5]) + x[3].scale(m[6])).0, (x[1].scale(m[7]) + x[2].scale(m[8]) + x[3].scale(m[9])).0, (x[4].scale(m[1]) + x[5].scale(m[2]) + x[6].scale(m[3])).0, (x[4].scale(m[4]) + x[5].scale(m[5]) + x[6].scale(m[6])).0, (x[4].scale(m[7]) + x[5].scale(m[8]) + x[6].scale(m[9])).0, (x[7].scale(m[0])).0] }
    }
}

impl<T: gx::Coef> From<gx::Prepared<gx::Unit<Odd>, Multivector, T, 10>> for Multivector<(Multivector,), T> {
    /// The dense map of the prepared action.
    #[inline]
    fn from(p: gx::Prepared<gx::Unit<Odd>, Multivector, T, 10>) -> Self {
        let m = p.m;
        Multivector { c: [[m[0], T::zero(), T::zero(), T::zero(), T::zero(), T::zero(), T::zero(), T::zero()], [T::zero(), m[1], m[2], m[3], T::zero(), T::zero(), T::zero(), T::zero()], [T::zero(), m[4], m[5], m[6], T::zero(), T::zero(), T::zero(), T::zero()], [T::zero(), m[7], m[8], m[9], T::zero(), T::zero(), T::zero(), T::zero()], [T::zero(), T::zero(), T::zero(), T::zero(), m[1], m[2], m[3], T::zero()], [T::zero(), T::zero(), T::zero(), T::zero(), m[4], m[5], m[6], T::zero()], [T::zero(), T::zero(), T::zero(), T::zero(), m[7], m[8], m[9], T::zero()], [T::zero(), T::zero(), T::zero(), T::zero(), T::zero(), T::zero(), T::zero(), m[0]]] }
    }
}

#[cfg(feature = "batch")]
impl gx::batch::SandwichKernel<Multivector, gx::batch::Certified> for Odd {
    type Y = Multivector;
    type Versor<T: gx::Coef> = gx::Unit<Odd<(), T>>;
    type Prepared<T: gx::Coef> = gx::Prepared<gx::Unit<Odd>, Multivector, T, 10>;
    #[inline(always)]
    fn wrap<T: gx::Coef>(v: Odd<(), T>) -> gx::Unit<Odd<(), T>> {
        gx::Unit::new_unchecked(v)
    }
    #[inline(always)]
    fn unwrap<T: gx::Coef>(v: gx::Unit<Odd<(), T>>) -> Odd<(), T> {
        v.into_inner()
    }
    #[inline(always)]
    fn prepare<T: gx::Coef>(v: gx::Unit<Odd<(), T>>) -> gx::Prepared<gx::Unit<Odd>, Multivector, T, 10> {
        gx::Prepare::<Multivector>::prepare(v)
    }
    #[inline(always)]
    fn map_prepared<T: gx::Coef, W: gx::Coef>(p: gx::Prepared<gx::Unit<Odd>, Multivector, T, 10>, mut f: impl FnMut(T) -> W) -> gx::Prepared<gx::Unit<Odd>, Multivector, W, 10> {
        let m = p.m;
        gx::Prepared::from_entries([f(m[0]), f(m[1]), f(m[2]), f(m[3]), f(m[4]), f(m[5]), f(m[6]), f(m[7]), f(m[8]), f(m[9])])
    }
    #[inline(always)]
    fn apply_prepared<T: gx::Coef>(p: gx::Prepared<gx::Unit<Odd>, Multivector, T, 10>, x: Multivector<(), T>) -> Multivector<(), T> {
        gx::Transform::transform(p, x)
    }
    #[inline(always)]
    fn apply<T: gx::Coef>(v: gx::Unit<Odd<(), T>>, x: Multivector<(), T>) -> Multivector<(), T> {
        gx::Transform::transform(v, x)
    }
}

impl<T: gx::Coef> gx::Outermorphism<Bivector> for Vector<(Vector,), T> {
    type Output = Bivector<(Bivector,), T>;
    /// The extension of a map on `Vector` to `Bivector`, factor by factor with `â§`.
    #[inline]
    fn outermorphism(self) -> Bivector<(Bivector,), T> {
        let t = self.c;
        let m0 = t[1][1] * t[2][2];
        let m3 = t[1][2] * t[2][0];
        let m4 = t[1][0] * t[2][1];
        let m7 = t[0][2] * t[2][1];
        let m8 = t[0][0] * t[2][2];
        let m11 = t[0][1] * t[2][0];
        let m12 = t[0][1] * t[1][2];
        let m15 = t[0][2] * t[1][0];
        let m16 = t[0][0] * t[1][1];
        let m18 = (-t[1][2]).mul_add(t[2][1], m0);
        let m19 = (-t[1][0]).mul_add(t[2][2], m3);
        let m20 = (-t[1][1]).mul_add(t[2][0], m4);
        let m21 = (-t[0][1]).mul_add(t[2][2], m7);
        let m22 = (-t[0][2]).mul_add(t[2][0], m8);
        let m23 = (-t[0][0]).mul_add(t[2][1], m11);
        let m24 = (-t[0][2]).mul_add(t[1][1], m12);
        let m25 = (-t[0][0]).mul_add(t[1][2], m15);
        let m26 = (-t[0][1]).mul_add(t[1][0], m16);
        Bivector { c: [[m18, m19, m20], [m21, m22, m23], [m24, m25, m26]] }
    }
}

impl<T: gx::Coef> gx::Outermorphism<Pseudoscalar> for Vector<(Vector,), T> {
    type Output = Pseudoscalar<(Pseudoscalar,), T>;
    /// The extension of a map on `Vector` to `Pseudoscalar`, factor by factor with `â§`.
    #[inline]
    fn outermorphism(self) -> Pseudoscalar<(Pseudoscalar,), T> {
        let t = self.c;
        let m0 = t[0][0] * t[1][1];
        let m2 = t[0][0] * t[1][2];
        let m4 = t[0][1] * t[1][0];
        let m5 = t[2][2] * m4;
        let m6 = t[0][1] * t[1][2];
        let m7 = t[2][0] * m6;
        let m8 = t[0][2] * t[1][0];
        let m10 = t[0][2] * t[1][1];
        let m12 = t[2][2].mul_add(m0, m7);
        let m13 = t[2][1].mul_add(m8, m12);
        let m14 = t[2][1].mul_add(m2, m5);
        let m15 = t[2][0].mul_add(m10, m14);
        let m16 = m13 - m15;
        Pseudoscalar { c: [[m16]] }
    }
}

