#[cfg(feature = "bytemuck")]
/// [`Scalar`] in the GPU layout of the `gax::wgsl` modules: its 1 coefficients in blade
/// order, four per `vec4<f32>` field, zero-padded (the WGSL struct `Scalar`).
#[repr(C, align(16))]
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct ScalarGpu {
    /// The coefficients, `c[i / 4][i % 4]` for coefficient `i`.
    pub c: [[f32; 4]; 1],
}

// The WGSL layout of `struct Scalar { c0: vec4<f32>, ... }`: size 16 per field, align 16.
#[cfg(feature = "bytemuck")]
const _: () = {
    assert!(core::mem::size_of::<ScalarGpu>() == 16);
    assert!(core::mem::align_of::<ScalarGpu>() == 16);
    assert!(core::mem::offset_of!(ScalarGpu, c) == 0);
};

// SAFETY: `repr(C, align(16))` over `[[f32; 4]; 1]` (size a multiple of 16): no padding
// bytes, and every bit pattern is a valid `f32`.
#[cfg(feature = "bytemuck")]
unsafe impl gx::bytemuck::Zeroable for ScalarGpu {}
// SAFETY: as above.
#[cfg(feature = "bytemuck")]
unsafe impl gx::bytemuck::Pod for ScalarGpu {}

#[cfg(feature = "bytemuck")]
impl From<Scalar<(), f32>> for ScalarGpu {
    #[inline]
    fn from(x: Scalar<(), f32>) -> Self {
        let mut c = [[0.0; 4]; 1];
        for (i, v) in x.c.iter().enumerate() {
            c[i / 4][i % 4] = *v;
        }
        ScalarGpu { c }
    }
}

#[cfg(feature = "bytemuck")]
impl From<gx::Unit<Scalar<(), f32>>> for ScalarGpu {
    #[inline]
    fn from(x: gx::Unit<Scalar<(), f32>>) -> Self {
        x.into_inner().into()
    }
}

#[cfg(feature = "bytemuck")]
impl From<ScalarGpu> for Scalar<(), f32> {
    #[inline]
    fn from(g: ScalarGpu) -> Self {
        Scalar::from_coeffs(core::array::from_fn(|i| g.c[i / 4][i % 4]))
    }
}

/// [`Scalar`] in the GPU layout of the `gax::wgsl` `f16` modules (`gax::vga3d_f16`): its 1
/// coefficients as IEEE binary16 bit patterns, four per `vec4<f16>` field, zero-padded.
#[repr(C, align(8))]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct ScalarGpu16 {
    /// The coefficients' `f16` bits, `c[i / 4][i % 4]` for coefficient `i`.
    pub c: [[u16; 4]; 1],
}

// The WGSL layout of `struct Scalar { c0: vec4<f16>, ... }`: size 8 per field, align 8.
#[cfg(feature = "bytemuck")]
const _: () = {
    assert!(core::mem::size_of::<ScalarGpu16>() == 8);
    assert!(core::mem::align_of::<ScalarGpu16>() == 8);
};

// SAFETY: `repr(C, align(8))` over `[[u16; 4]; 1]` (size a multiple of 8): no padding bytes,
// and every bit pattern is a valid `u16`.
#[cfg(feature = "bytemuck")]
unsafe impl gx::bytemuck::Zeroable for ScalarGpu16 {}
// SAFETY: as above.
#[cfg(feature = "bytemuck")]
unsafe impl gx::bytemuck::Pod for ScalarGpu16 {}

#[cfg(feature = "bytemuck")]
impl From<Scalar<(), f32>> for ScalarGpu16 {
    /// Each coefficient rounded to the nearest `f16`.
    #[inline]
    fn from(x: Scalar<(), f32>) -> Self {
        let mut c = [[0; 4]; 1];
        for (i, v) in x.c.iter().enumerate() {
            c[i / 4][i % 4] = gx::gpu::f16_bits(*v);
        }
        ScalarGpu16 { c }
    }
}

#[cfg(feature = "bytemuck")]
impl From<ScalarGpu16> for Scalar<(), f32> {
    #[inline]
    fn from(g: ScalarGpu16) -> Self {
        Scalar::from_coeffs(core::array::from_fn(|i| gx::gpu::f16_to_f32(g.c[i / 4][i % 4])))
    }
}

#[cfg(feature = "bytemuck")]
/// [`Vector`] in the GPU layout of the `gax::wgsl` modules: its 3 coefficients in blade
