#[cfg(feature = "bytemuck")]
/// The map as a WGSL `mat3x3<f32>` (columns are inputs; transposes the output-first layout).
impl From<Vector<(Vector,), f32>> for gx::GpuMat<3> {
    #[inline]
    fn from(m: Vector<(Vector,), f32>) -> Self {
        let mut cols = [[0.0; 4]; 3];
        for (o, row) in m.c.iter().enumerate() {
            for (i, col) in cols.iter_mut().enumerate() {
                col[o] = <(Vector,) as gx::Slots>::get_flat(row, i);
            }
        }
        gx::GpuMat { cols }
    }
}

#[cfg(feature = "bytemuck")]
impl From<gx::GpuMat<3>> for Vector<(Vector,), f32> {
    #[inline]
    fn from(g: gx::GpuMat<3>) -> Self {
        Vector::from_coeffs(core::array::from_fn(|o| {
            <(Vector,) as gx::Slots>::from_flat(&mut |i| g.cols[i][o], 0)
        }))
    }
}

